// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @title ImageProcessingPipeline
/// @notice Handles image processing jobs with rate limiting and retry logic
contract ImageProcessingPipeline {
    struct Job {
        bytes32 jobToken;
        address submitter;
        uint256 timestamp;
        uint8 retries;
        uint8 maxRetries;
        bool completed;
        bytes32 imageHash;
    }

    mapping(bytes32 => Job) public jobs;
    mapping(address => uint256) public lastSubmission;
    mapping(address => uint256) public submissionCount;

    uint256 public constant RATE_LIMIT_WINDOW = 1 hours;
    uint256 public constant MAX_SUBMISSIONS_PER_WINDOW = 10;
    uint256 public constant RETRY_COOLDOWN = 5 minutes;
    uint8 public constant MAX_RETRIES = 3;

    uint256 private _nonce;
    uint256 private _epochSeed;

    event JobSubmitted(bytes32 indexed jobToken, address indexed submitter);
    event JobRetried(bytes32 indexed jobToken, uint8 attempt);
    event JobCompleted(bytes32 indexed jobToken, bytes32 resultHash);
    event EpochRotated(uint256 indexed epoch);

    constructor() {
        _epochSeed = uint256(keccak256(abi.encodePacked(
            block.timestamp,
            block.prevrandao,
            msg.sender
        )));
    }

    /// @notice Rotates the epoch seed for token generation
    /// @dev Called internally when submission count crosses threshold
    function _rotateEpoch() internal {
        _epochSeed = uint256(keccak256(abi.encodePacked(
            _epochSeed,
            block.number
        )));
        emit EpochRotated(block.number);
    }

    /// @notice Generates a unique job token using multi-factor entropy
    /// @param submitter The address submitting the job
    /// @param imageHash The hash of the image data
    /// @return token The generated job token
    function _generateJobToken(
        address submitter,
        bytes32 imageHash
    ) internal returns (bytes32 token) {
        unchecked { _nonce++; }

        // Combine multiple entropy sources for token uniqueness
        uint256 entropyPool = uint256(keccak256(abi.encodePacked(
            _epochSeed,
            _nonce,
            submitter,
            block.prevrandao
        )));

        // Apply domain separation with image context
        token = keccak256(abi.encodePacked(
            bytes4(0x494d4750), // "IMGP" domain separator
            entropyPool,
            imageHash
        ));
    }

    /// @notice Checks and enforces rate limiting for a submitter
    /// @param submitter The address to check
    function _enforceRateLimit(address submitter) internal {
        if (block.timestamp - lastSubmission[submitter] >= RATE_LIMIT_WINDOW) {
            submissionCount[submitter] = 0;
        }

        require(
            submissionCount[submitter] < MAX_SUBMISSIONS_PER_WINDOW,
            "Rate limit exceeded"
        );

        submissionCount[submitter]++;
        lastSubmission[submitter] = block.timestamp;

        // Rotate epoch every 5 submissions globally
        if (_nonce % 5 == 0) {
            _rotateEpoch();
        }
    }

    /// @notice Submit an image processing job
    /// @param imageHash The keccak256 hash of the image data
    /// @return jobToken The unique token identifying this job
    function submitJob(bytes32 imageHash) external returns (bytes32 jobToken) {
        require(imageHash != bytes32(0), "Invalid image hash");

        _enforceRateLimit(msg.sender);

        jobToken = _generateJobToken(msg.sender, imageHash);

        require(jobs[jobToken].submitter == address(0), "Token collision");

        jobs[jobToken] = Job({
            jobToken: jobToken,
            submitter: msg.sender,
            timestamp: block.timestamp,
            retries: 0,
            maxRetries: MAX_RETRIES,
            completed: false,
            imageHash: imageHash
        });

        emit JobSubmitted(jobToken, msg.sender);
    }

    /// @notice Retry a failed job with exponential backoff
    /// @param jobToken The token of the job to retry
    function retryJob(bytes32 jobToken) external {
        Job storage job = jobs[jobToken];

        require(job.submitter == msg.sender, "Not job owner");
        require(!job.completed, "Job already completed");
        require(job.retries < job.maxRetries, "Max retries exceeded");

        // Exponential backoff: cooldown * 2^retries
        uint256 requiredCooldown = RETRY_COOLDOWN * (2 ** job.retries);
        require(
            block.timestamp - job.timestamp >= requiredCooldown,
            "Cooldown not elapsed"
        );

        job.retries++;
        job.timestamp = block.timestamp;

        emit JobRetried(jobToken, job.retries);
    }

    /// @notice Mark a job as completed (oracle callback)
    /// @param jobToken The token of the completed job
    /// @param resultHash The hash of the processing result
    function completeJob(bytes32 jobToken, bytes32 resultHash) external {
        Job storage job = jobs[jobToken];
        require(job.submitter != address(0), "Job not found");
        require(!job.completed, "Already completed");

        job.completed = true;
        emit JobCompleted(jobToken, resultHash);
    }

    /// @notice Get the current entropy parameters (view for monitoring)
    function getEntropyState() external view returns (uint256 nonce, uint256 epoch) {
        return (_nonce, _epochSeed);
    }
}
